package B4;
import java.io.*;import java.nio.file.*;import java.sql.*;import java.util.*;
public class MigratePasses{public static void main(String[]a)throws Exception{String url=System.getenv().getOrDefault("DB_URL","jdbc:mysql://localhost:3306/transport_test"),user=System.getenv().getOrDefault("DB_USER","root"),pwd=System.getenv().getOrDefault("DB_PASSWORD","");Path file=Path.of(a.length>0?a[0]:"passes.csv");int ok=0,bad=0;List<String[]>batch=new ArrayList<>();try(BufferedReader r=Files.newBufferedReader(file);Connection c=DriverManager.getConnection(url,user,pwd)){String line;while((line=r.readLine())!=null){String[]p=line.split(",",-1);try{if(p.length!=5||p[0].isBlank()||p[1].isBlank())throw new IllegalArgumentException("invalid fields");Integer.parseInt(p[3]);if(Double.parseDouble(p[4])<0)throw new IllegalArgumentException("negative amount");batch.add(p);}catch(RuntimeException e){bad++;System.err.println("Rejected: "+line+" : "+e.getMessage());}}ok=B3.PassLoader.loadAll(c,batch);DatabaseMetaData m=c.getMetaData();System.out.println("Database: "+m.getDatabaseProductName());System.out.println("Driver: "+m.getDriverVersion());try(ResultSet t=m.getTables(null,null,"%",new String[]{"TABLE"})){while(t.next())System.out.println("Table: "+t.getString("TABLE_NAME"));}}System.out.println("Loaded="+ok+", rejected="+bad);}}
